```python
# Simulación mínima de estimación y planificación en Scrum
backlog = {"login": 5, "registro": 8, "perfil": 3}   # story points
capacity = 10                                      # puntos disponibles en el sprint

sprint = {}
remaining = capacity
for task, pts in backlog.items():
    if pts <= remaining:
        sprint[task] = pts
        remaining -= pts

print("Sprint seleccionado:", sprint)
# Salida: Sprint seleccionado: {'login': 5, 'perfil': 3}
```
